inline bool VerifyCardUnion(::flatbuffers::Verifier& verifier, const void* obj, CardUnion type) {
  switch (type) {
    case CardUnion_NONE: {
      return true;
    }
    case CardUnion_Nothing: {
      auto ptr = reinterpret_cast<const poker_engine::fbs::Nothing*>(obj);
      return verifier.VerifyTable(ptr);
    }
    case CardUnion_Card: {
      auto ptr = reinterpret_cast<const poker_engine::fbs::Card*>(obj);
      return verifier.VerifyTable(ptr);
    }
    default:
      return true;
  }
}

inline bool VerifyCardUnionVector(::flatbuffers::Verifier& verifier,
                                  const ::flatbuffers::Vector<::flatbuffers::Offset<void>>* values,
                                  const ::flatbuffers::Vector<uint8_t>* types) {
  if (!values || !types) return !values && !types;
  if (values->size() != types->size()) return false;
  for (::flatbuffers::uoffset_t i = 0; i < values->size(); ++i) {
    if (!VerifyCardUnion(verifier, values->Get(i), types->GetEnum<CardUnion>(i))) {
      return false;
    }
  }
  return true;
}

